import{_ as E,l as i,o as t,c as o,v as s,p as d,x as r,d as n,i as B,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"停牌复牌与信息窗口","description":"","frontmatter":{"title":"停牌复牌与信息窗口","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-halt-resume.md","filePath":"quant/cn-halt-resume.md","lastUpdated":1789023840000}'),h={name:"quant/cn-halt-resume.md"};function A(u,e,c,m,f,q){const l=i("Mermaid");return t(),o("div",null,[e[1]||(e[1]=s('<h1 id="停牌复牌与信息窗口" tabindex="-1">停牌复牌与信息窗口 <a class="header-anchor" href="#停牌复牌与信息窗口" aria-label="Permalink to &quot;停牌复牌与信息窗口&quot;">​</a></h1><div class="epigraph"><p>上市公司筹划发行股份购买资产申请停牌的，停牌时间不超过十个交易日；未能按期披露预案的，应当终止筹划并复牌。以不停牌为原则、停牌为例外，保护投资者的交易权利。</p><footer>—— 沪深交易所上市公司停复牌业务指引（筹划重大事项）；深圳证券交易所《上市公司自律监管指引第 6 号——停复牌》（2025 年修订）</footer></div><p><a href="/quant/cn-st-delist">上一课</a>把 ST/*ST 与四类退市写成规则触发的状态：交易类按收盘计、锁定后通常无整理期，财务类有年报周期与撤销路径。缺口是交易时钟本身会被切断：停牌分盘中临停与跨日事项停牌，前者当日必复，后者把信息压缩到复牌跳空。重组停牌原则上不超过 10 个交易日，现金类重组原则上不停牌。本课写停复牌与信息窗口，不重写退市计数。正股停牌如何破坏转债、两融与 ETF 篮子，接到已写的联立与申赎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>停牌分两类，不可混用。一类是盘中临时停牌：无涨跌幅限制证券（如新股前五日）触及 30%、60% 等阈值停牌十分钟量级，可转债上市首日触及 20%、30% 临停三十分钟或直至 14:57。临停当日必复，不跨夜。另一类是重大事项停牌：重组、澄清、监管调查、异常波动核查等，可以跨交易日。跨日停牌期间没有可成交价格，因子、beta、波动与对冲比率都必须冻结或改用代理，而不能把最后一笔成交向前填。</p><p>信息窗口是停牌的原因，不是停牌的长度。重组停牌须在期限内披露预案或终止并复牌；异常波动、严重异常波动由交易所要求核查公告，可能盘中或隔夜短暂停牌。窗口内公司可继续谈判，市场不能用订单表达。复牌首日的收益因此包含：已公告信息、仍未公告的残余不确定性、以及涨跌停造成的延迟发现。用停牌前二十日的波动去缩放复牌日收益，会把一个跳跃过程当成扩散。</p><h3 id="重组停牌的十日上限与例外" tabindex="-1">重组停牌的十日上限与例外 <a class="header-anchor" href="#重组停牌的十日上限与例外" aria-label="Permalink to &quot;重组停牌的十日上限与例外&quot;">​</a></h3><p>现行指引仅允许发行股份或定向可转债购买资产等需要锁价的重组申请停牌，现金购买或出售原则上交易不中断。停牌不超过 10 个交易日，更换标的也累计计算；国家部门另有要求的，连续停牌原则上不超过 25 个交易日；军工秘密等从其规定。方案重大调整可再申请不超过 5 个交易日。期限届满未披露预案须终止筹划并复牌。这意味着「停牌=重大利好正在酝酿」不再是稳定的条件期望：到期强制复牌可以把失败的重组一次性定价。回测若仍用 2015 年动辄数月停牌的样本估计复牌漂移，会高估停牌期权的价值。</p><p><span class="marginnote">停牌期间大宗交易亦不接受。15:00 仍停牌的证券，当日不再接受大宗申报。用停牌日的「影子价格」去匹配大宗或转债，没有交易所成交与之对应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据层应维护停复牌事件表：证券代码、停牌原因分类、起止日、是否盘中临停、复牌首日是否涨跌停、公告时间戳。收益计算在停牌区间记为缺失而不是零；因子暴露用停牌前最后有效日冻结，复牌后再更新。对冲账户在停牌腿上改为「不可调仓」：股指期货与 ETF 仍在交易，组合会被动露出指数敞口，这应记入<a href="/quant/index-arb">指数套利</a>与<a href="/quant/cn-etf-creation">ETF 申赎与 IOPV</a>的缺腿，而不是继续按旧 beta 再平衡。</p><p>复牌日的集合竞价是信息释放的主通道。有效申报仍受涨跌幅限制，主板 10%、科创板与创业板 20%、风险警示 5%，信息再大也不能在首笔之外一次性走完。连续涨跌停把窗口拉成多日障碍，已实现波动在封板日接近涨跌幅本身，方向误差在未打开前无法修正。事件研究应以「复牌后首次未封板日」为价格发现完成的代理，同时报告封板持续天数，而不是只报复牌日超额收益。</p><h3 id="转债、两融与篮子的同步失败" tabindex="-1">转债、两融与篮子的同步失败 <a class="header-anchor" href="#转债、两融与篮子的同步失败" aria-label="Permalink to &quot;转债、两融与篮子的同步失败&quot;">​</a></h3><p>正股停牌时，可转债可能继续交易，平价所用 \\(S\\) 陈旧，<a href="/quant/cb-equity-link">转债与正股联立</a>的 delta 失效。融资融券担保证券停牌，维持担保比例用的市值可能仍按停牌价计，复牌跌停会令担保缺口一次性出现，触发<a href="/quant/cn-margin-trading">融资融券保证金与强平</a>的追保。ETF 成分停牌则 IOPV 按停牌前价格跳动，现金替代与退补把执行风险推到事后。这三条链路要求：停牌名字从可对冲集合删除，相关衍生品与篮子的残差单独设限额。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>停牌把知情交易从订单簿转移到公告。指引要求停牌期间披露进展，期限届满必须给一个可定价的文本（预案或终止）。文本落地的时点往往在非交易时段，复牌集合竞价是第一笔公开出清。买卖双方在涨跌幅内报单，未成交部分排队，打开后才恢复连续发现。因此复牌日的开盘价相对停牌前收盘的跳空，是窗口内信息的压缩，而不是隔夜因子。</p><p>异常波动停牌更短，功能是强制披露而非锁价。连续三日涨跌幅偏离值达到阈值、或严重异常波动标准触发后，公司核查并公告，停牌可能只有一个交易日或盘中若干分钟。这类窗口的信息含量低于重组预案，复牌跳空的均值更接近零、方差仍然高。把所有停牌原因放进同一个「停牌溢价」估计，会把核查停牌的噪声当成重组停牌的漂移。</p><p><span class="marginnote">盘中临时停牌的时钟以交易所公告为准，跨越 14:57 的临停于 14:57 复牌并进入收盘集合。用「停牌 30 分钟」的名义时长去对齐 tick，会在尾盘把复牌集合错写成连续竞价。</span></p><h3 id="不可交易区间对因子的污染" tabindex="-1">不可交易区间对因子的污染 <a class="header-anchor" href="#不可交易区间对因子的污染" aria-label="Permalink to &quot;不可交易区间对因子的污染&quot;">​</a></h3><p>动量、反转、波动率若把停牌日当成交日、用最后价格填前，会把陈旧价格写成低波动、把复牌跳空写成单日反转。正确处理是：停牌日不进入日频收益；复牌跳空单独作为事件收益；停牌超过若干日的名字在停牌期间从月频组合里移除或冻结权重。对隔夜因子，停牌跨越的日历夜不是可交易的隔夜，<a href="/quant/calendar-overnight">日历效应与隔夜</a>应把这些夜剔除。否则会把「无成交的夜」算进隔夜风险溢价。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用停牌时长预测信息方向。不要把 10 个交易日上限当成一定停满 10 天。不要在复牌首日按正常冲击模型估计可成交量——涨跌停使冲击变成排队与开板。回测须使用历史指引版本：2018 年压缩停牌、其后「以不停牌为原则」的修订，以及 2025 年深市自律监管指引的文本。军工、国家战略项目的例外会使极少数名字仍出现较长停牌，样本极厚尾，不宜进入无条件均值。</p><p>容量上，复牌日往往一字板，策略若计划在复牌日调仓，应假设成交发生在首次打开之后，并允许永远打不开直至下一状态（再停牌或退市）。报告应分原因披露：重组成功披露、重组终止复牌、异常波动核查、监管调查，各自的跳空分布与封板天数。</p><p><span class="marginnote">停牌不是风险管理工具。组合不能靠「希望它停牌」来规避下跌；能做的是事先规定停牌腿的替代对冲（指数、行业 ETF）以及复牌前不得加仓。</span></p>',24)),(t(),d(p,null,{default:r(()=>[B(l,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E9%87%8D%E5%A4%A7%E4%BA%8B%E9%A1%B9%20%2F%20%E5%BC%82%E5%B8%B8%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20HALT%5B%22%E5%81%9C%E7%89%8C%EF%BC%9A%E8%BF%9E%E7%BB%AD%E7%AB%9E%E4%BB%B7%E5%88%87%E6%96%AD%22%5D%0A%20%20HALT%20--%3E%20INFO%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%E6%8A%AB%E9%9C%B2%E6%88%96%E5%88%B0%E6%9C%9F%E5%BC%BA%E5%88%B6%E5%A4%8D%E7%89%8C%22%5D%0A%20%20INFO%20--%3E%20AUCT%5B%22%E5%A4%8D%E7%89%8C%E9%9B%86%E5%90%88%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20AUCT%20--%3E%7C%22%E6%9C%AA%E8%B6%8A%E6%9D%BF%22%7C%20CONT%5B%22%E8%BF%9E%E7%BB%AD%E5%8F%91%E7%8E%B0%22%5D%0A%20%20AUCT%20--%3E%7C%22%E6%B6%A8%E8%B7%8C%E5%81%9C%22%7C%20LIMIT%5B%22%E5%A4%9A%E6%97%A5%E5%B0%81%E6%9D%BF%E5%BB%B6%E8%BF%9F%E5%8F%91%E7%8E%B0%22%5D%0A%20%20HALT%20--%3E%20LEG%5B%22%E8%BD%AC%E5%80%BA%20%2F%20%E4%B8%A4%E8%9E%8D%20%2F%20ETF%20%E7%BC%BA%E8%85%BF%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[n("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"停牌分盘中临停与跨日事项停牌；前者当日必复，后者把信息压缩到复牌跳空。"),a("li",null,"重组停牌原则上不超过 10 个交易日，现金类重组原则上不停牌，期限届满须披露或终止。"),a("li",null,"复牌价格发现受涨跌幅约束，事件收益应看到首次未封板，而不是只看复牌日。"),a("li",null,"正股停牌会破坏转债平价、两融担保与 ETF 篮子，须从可对冲集合剔除。"),a("li",null,"因子不得对停牌日填前；隔夜与反转样本应剔除不可交易夜。"),a("li",null,"出处：沪深交易所上市公司筹划重大事项停复牌业务指引；《深圳证券交易所上市公司自律监管指引第 6 号——停复牌》（2025 年修订）；可转债上市首日临停见可转债交易实施细则。")],-1))])}const b=E(h,[["render",A]]);export{C as __pageData,b as default};
